import{_ as t,o as n,c as d,a3 as r}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Bildverbindung in MiniTavern","description":"Einstellungen → Bildgenerierung → Bildverbindung — lokal A1111 / ComfyUI oder Cloud-Image-API.","frontmatter":{"title":"Bildverbindung in MiniTavern","description":"Einstellungen → Bildgenerierung → Bildverbindung — lokal A1111 / ComfyUI oder Cloud-Image-API.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Bildverbindung in MiniTavern · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Einstellungen → Bildgenerierung → Bildverbindung — lokal A1111 / ComfyUI oder Cloud-Image-API."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/local/image-gen/connect-app"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/local/image-gen/connect-app"}]]},"headers":[],"relativePath":"de/local/image-gen/connect-app.md","filePath":"de/local/image-gen/connect-app.md","lastUpdated":1787224147000}'),i={name:"de/local/image-gen/connect-app.md"};function a(l,e,o,s,h,g){return n(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="bildverbindung-in-minitavern" tabindex="-1">Bildverbindung in MiniTavern <a class="header-anchor" href="#bildverbindung-in-minitavern" aria-label="Permalink to &quot;Bildverbindung in MiniTavern&quot;">​</a></h1><p>App-Pfad: <strong>Einstellungen → Bildgenerierung → Bildverbindung</strong>.</p><p>Parameter, Antwortbilder, Keywords: <a href="/ultra_guides/de/manual/model-link#bildgenerierung-verbindung--antwortbilder--schlüsselwörter">Modellverbindung · Bild</a>.</p><h2 id="neue-bildverbindung" tabindex="-1">Neue Bildverbindung <a class="header-anchor" href="#neue-bildverbindung" aria-label="Permalink to &quot;Neue Bildverbindung&quot;">​</a></h2><ol><li>MiniTavern → unten <strong>Einstellungen</strong>.</li><li><strong>Bildgenerierung</strong> → <strong>Bildverbindung</strong>.</li><li><strong>Neu</strong>.</li><li><strong>Plattform</strong>, Base URL / API Key / Modell je Plattform.</li><li><strong>Testen</strong>, speichern, ggf. als Standard.</li></ol><h2 id="lokal-a1111" tabindex="-1">Lokal A1111 <a class="header-anchor" href="#lokal-a1111" aria-label="Permalink to &quot;Lokal A1111&quot;">​</a></h2><p>Zuerst <a href="/ultra_guides/de/local/image-gen/a1111">A1111 mit <code>--api --listen</code></a>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Beispiel</th></tr></thead><tbody><tr><td>Plattform</td><td><strong>A1111(SD WebUI)</strong> (oder Custom A1111)</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:7860</code></td></tr><tr><td>API Key</td><td>meist leer; bei <code>--api-auth</code> laut Hinweis</td></tr><tr><td>Modell</td><td>leer oder Checkpoint-Name aus WebUI (App-Liste)</td></tr></tbody></table><p><code>YOUR_PC_IP</code> = LAN-IP.<br><strong>Nicht</strong> <code>http://127.0.0.1:7860</code> (das ist der PC, nicht das Handy).</p><h2 id="lokal-comfyui" tabindex="-1">Lokal ComfyUI <a class="header-anchor" href="#lokal-comfyui" aria-label="Permalink to &quot;Lokal ComfyUI&quot;">​</a></h2><p>Zuerst <a href="/ultra_guides/de/local/image-gen/comfyui">ComfyUI mit <code>--listen</code></a>.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Beispiel</th></tr></thead><tbody><tr><td>Plattform</td><td><strong>ComfyUI</strong> (oder Custom ComfyUI)</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8188</code> (Desktop oft <code>:8000</code>)</td></tr><tr><td>API Key</td><td>meist leer</td></tr><tr><td>Modell / Checkpoint</td><td>aus der App-Liste; Datei muss auf dem PC liegen</td></tr></tbody></table><p>Test fehlgeschlagen: dieselbe Base URL im Handy-Browser — Firewall oder fehlendes Listen?</p><h2 id="cloud-bild-optional" tabindex="-1">Cloud-Bild (optional) <a class="header-anchor" href="#cloud-bild-optional" aria-label="Permalink to &quot;Cloud-Bild (optional)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plattform</th><th>Wann</th></tr></thead><tbody><tr><td>ChatGPT(OpenAI)</td><td>offizielle Images API (meist bezahlt)</td></tr><tr><td>Gemini(Google)</td><td>Gemini-Image (meist Paid laut Google)</td></tr><tr><td>OpenRouter</td><td>Upstream mit Image</td></tr><tr><td>Qwen</td><td>Wanxiang / Qwen-Image (Bailian-Free prüfen)</td></tr><tr><td>Custom (OpenAI Images)</td><td>SiliconFlow, Agnes usw. mit <code>/images/generations</code> (Image-to-Image auch generations, nicht <code>/images/edits</code>)</td></tr></tbody></table><p>Free Cloud: <a href="/ultra_guides/de/free-cloud/#kostenlose-bildgenerierung">Kostenlose Cloud · Bild</a>.</p><h2 id="bild-im-chat" tabindex="-1">Bild im Chat <a class="header-anchor" href="#bild-im-chat" aria-label="Permalink to &quot;Bild im Chat&quot;">​</a></h2><p>Default-Bildverbindung (Hauptchat-Modell auch nötig für Analyse/Prompt-Rewrite):</p><table tabindex="0"><thead><tr><th>Einstieg</th><th>Hinweis</th></tr></thead><tbody><tr><td><code>/imagine Prompt</code></td><td>freies Bild. Hauptmodell: dialogbezogen («Selfie von dir» → Dialog + Charakterreferenz) oder unabhängig («Foto eines Hundes»). Anhänge im Eingabefeld: Modell sieht sie beim Promptschreiben und als Referenz; Charakter-/User-Bild-Entscheidung bleibt separat. Anhänge in der kleinen Bubble-Vorschau. Anzahl: <strong>Bildeinstellungen → Generierungsanzahl</strong>. Fehler bleibt, Retry möglich</td></tr><tr><td><code>/imagine scene</code> oder Anhang → Nach Story</td><td>aktuelle Szene aus kürzlichem Dialog, fest 1</td></tr><tr><td><code>/imagine last</code> oder Anhang → Nach letzter Nachricht</td><td>nach letzter Nachricht, fest 1</td></tr><tr><td><code>/imagine background</code> oder Anhang → Hintergrund</td><td>Umgebung, fest 1</td></tr><tr><td>Lang drücken → Bild</td><td>nach dieser Bubble, fest 1</td></tr><tr><td>Antwortbilder (intelligent / Keyword)</td><td>in Bildeinstellungen «Antwortbilder» an und Auslöser wählen. Normale Nachrichten (mit Anhang) → Bypass-Bild, fest 1; Anhang = Stil</td></tr></tbody></table><p>Ohne Bildverbindung: vier Anhang-Modi oder <code>/imagine</code> → «Zu Einstellungen / Abbrechen», kein Toast, Eingabe bleibt. Intelligent/Keyword ohne Verbindung: Toast. Antwortbilder-Schalter ohne Verbindung: Modal, Schalter bleibt aus.</p><p>Nur Bild ohne Chat-Modell: Einstiege mit Rewrite scheitern.</p><h2 id="fehler-kurzcheck" tabindex="-1">Fehler-Kurzcheck <a class="header-anchor" href="#fehler-kurzcheck" aria-label="Permalink to &quot;Fehler-Kurzcheck&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Prüfen</th></tr></thead><tbody><tr><td>Test / Timeout</td><td>Dienst läuft? <code>--api</code> / <code>--listen</code>? IP/Port? gleiches Wi‑Fi?</td></tr><tr><td>Browser am PC ok, Handy nicht</td><td>Firewall; Gastnetz; <code>127.0.0.1</code> eingetragen</td></tr><tr><td>A1111 404</td><td>kein <code>--api</code>; Base URL mit Extra-Pfad</td></tr><tr><td>Comfy dreht endlos</td><td>Comfy-Queue/Fehler; VRAM; kein Checkpoint</td></tr><tr><td>Referenz, aber Gesicht falsch (Comfy)</td><td>Default-Workflow ohne Referenz → A1111 oder Cloud</td></tr><tr><td><code>/imagine</code>-Fehler-Bubble weg</td><td>Fehler bleibt mit Retry; Stop entfernt unfertige Platzhalter</td></tr></tbody></table><p>Chat-Fehlercodes: <a href="/ultra_guides/de/manual/errors">Fehlercodes</a>.</p>',24)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
